<?php
/** Ejecutar por CLI cada 15 minutos. No se expone una ruta HTTP. */
if(PHP_SAPI!=='cli')exit(1);require_once __DIR__.'/../app/config/conexion.php';require_once __DIR__.'/../app/services/operaciones.php';
if(!in_array('--ejecutar',$argv,true))exit("Usa --ejecutar.\n");
$q=$conexion->query("SELECT c.*,p.correo FROM citas c JOIN pacientes p ON p.id=c.paciente_id WHERE c.estado='confirmado' AND (c.fecha_cita=CURDATE() OR c.fecha_cita=DATE_ADD(CURDATE(),INTERVAL 1 DAY)) AND TIMESTAMP(c.fecha_cita,c.hora_cita)>NOW() AND TIMESTAMP(c.fecha_cita,c.hora_cita)<=DATE_ADD(NOW(),INTERVAL 24 HOUR)");$n=0;
foreach($q->fetchAll() as $c){$clave='recordatorio:'.$c['id'].':'.$c['fecha_cita'].':'.$c['hora_cita'];$q=$conexion->prepare('SELECT id FROM correos_pendientes WHERE clave_evento=?');$q->execute([$clave]);if($q->fetchColumn())continue;
$conexion->beginTransaction();$texto='Recuerda tu cita '.codigo_cita($c['id']).' el '.$c['fecha_cita'].' a las '.substr($c['hora_cita'],0,5).'. Revisa los detalles en tu cuenta.';notificar_cita($c['paciente_id'],'Recordatorio de cita',$texto,$c['id']);$correo=$c['correo'];if(!$correo){$q=$conexion->prepare('SELECT p.correo FROM responsables_pacientes r JOIN pacientes p ON p.id=r.responsable_id WHERE r.paciente_id=? AND p.correo IS NOT NULL LIMIT 1');$q->execute([$c['paciente_id']]);$correo=$q->fetchColumn();}if($correo)correo_cita_preferido($c['paciente_id'],'Recordatorio de cita',$texto,'recordatorios_email',$clave); $conexion->prepare("INSERT IGNORE INTO correos_pendientes(para,asunto,mensaje,estado,clave_evento) VALUES('registro@invalid.local','Recordatorio procesado',?,'interno',?)")->execute([$texto,$clave]); if(!$correo) $conexion->prepare("INSERT IGNORE INTO correos_pendientes(para,asunto,mensaje,estado,clave_evento) VALUES('sin-correo@invalid.local','Recordatorio interno',?,'interno',?)")->execute([$texto,$clave]);$conexion->commit();$n++;}
procesar_correos();
$privado=directorio_privado('respaldos');$marca=$privado.'/ultimo_programado.txt';if(!is_file($marca)||trim(file_get_contents($marca))!==date('Y-m-d')){$comando=escapeshellarg(PHP_BINARY).' '.escapeshellarg(__DIR__.'/respaldo.php');exec($comando,$salida,$codigo);if($codigo===0)file_put_contents($marca,date('Y-m-d'));else registro_operativo('respaldo_fallido',['codigo'=>$codigo]);}
$retencion=max(1,min(30,(int)($config['backup_retention_days']??30)));
foreach(glob($privado.'/*')?:[] as $f)if(is_file($f)&&preg_match('/\.(sql|json)$/',$f)&&filemtime($f)<time()-$retencion*86400)unlink($f);
$conexion->exec('DELETE FROM recuperaciones WHERE vence_en<DATE_SUB(NOW(),INTERVAL 7 DAY)');$conexion->exec('DELETE FROM verificaciones_correo WHERE expira<DATE_SUB(NOW(),INTERVAL 7 DAY)');$conexion->exec("UPDATE lista_espera SET estado='vencida' WHERE hasta<CURDATE() AND estado IN('activa','ofertada')");
echo "Mantenimiento completado. Recordatorios nuevos: $n.\n";
